// Единая точка входа бота канала Рыжа. Кто редактор — решает следующая нода
// (таблица ryzh_editors), здесь только разбор апдейта.
// Случаи: кнопка черновика или меню тем; команда меню; текст-правка (reply на черновик или
// просто текст); всё остальное — подсказка.
const j = $input.first().json;

const cq = j.callback_query;
if (cq) {
  const [act, id, extra] = (cq.data || '').split(':');
  const base = {
    chat_id: cq.from.id,
    by: cq.from.first_name || cq.from.username || String(cq.from.id),
    callback_query_id: cq.id,
    message_id: cq.message?.message_id ?? null,
  };
  const POST_KINDS = { pok: 'approve', pno: 'reject', pim: 'redraw', pmt: 'other',
                       // старые кнопки на черновиках, разосланных до меню тем
                       pnx: 'other', ppv: 'other' };
  if (POST_KINDS[act]) return [{ json: { ...base, kind: POST_KINDS[act], post_id: Number(id) } }];
  if (act === 'pmn') return [{ json: { ...base, kind: 'page', page: Number(id) } }];
  if (act === 'ptp') return [{ json: { ...base, kind: 'pick', topic_id: Number(id) } }];
  if (act === 'ptd') return [{ json: { ...base, kind: 'drop', topic_id: Number(id), page: Number(extra) } }];
  if (act === 'pnop') return [{ json: { ...base, kind: 'nop' } }];
  return [];
}

const m = j.message || {};
if (!m.from || m.chat?.type !== 'private') return [];  // только личка

const text = (m.text || '').trim();
if (/^\/(topics|темы)(@\w+)?$/i.test(text)) {
  return [{ json: { kind: 'menu', chat_id: m.from.id } }];
}
if (!text || text.startsWith('/')) {
  return [{ json: { kind: 'help', chat_id: m.from.id } }];
}

// Правка. Если это ответ на сообщение с черновиком — привязываемся к нему точно,
// иначе правим последний висящий черновик.
return [{ json: {
  kind: 'edit',
  chat_id: m.from.id,
  edit_note: text,
  reply_to: m.reply_to_message?.message_id ?? null,
}}];

