// Меню тому, кто спросил. message_id есть у кнопок: тогда правим сообщение на месте.
const r = $('Route').first().json;
return [{ json: { page: r.page ?? 0, chat_id: r.chat_id, message_id: r.message_id ?? null } }];

// Страница копилки. Кнопок у Telegram-ноды всегда 5+5+2 (набор фиксирован в параметрах),
// поэтому пустые места занимает «·» с callback pnop.
const RUBRICS = { price: 'Почём белок', swap: 'Вместо этого', recipe: 'Рецепт Рыжа' };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => { s = String(s ?? '').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const NOP = { t: '·', cb: 'pnop' };
const m = $input.first().json;
const targets = m.chat_id ? [m.chat_id] : (m.editors || []);
if (!targets.length) throw new Error('ryzh_editors пуст — некому слать меню');

const rows = m.rows || [];
const pages = Math.ceil(m.total / 5) || 1;
const lines = rows.map((r, i) => {
  const donor = (String(r.note || '').match(/@\w+/) || ['вручную'])[0];
  const where = [RUBRICS[r.rubric] || r.rubric, donor, r.score ? `×${r.score}` : ''].filter(Boolean).join(' · ');
  return `<b>${i + 1}. ${esc(r.title)}</b>\n${esc(where)}` + (r.angle ? `\n<i>${esc(cut(r.angle, 110))}</i>` : '');
});
const text = `🦊 <b>Темы</b> · стр. ${m.page + 1}/${pages} · всего ${m.total}\n\n${lines.join('\n\n')}`;
const slot = i => rows[i];
const pick = [0, 1, 2, 3, 4].map(i => slot(i) ? { t: String(i + 1), cb: `ptp:${slot(i).id}` } : NOP);
const drop = [0, 1, 2, 3, 4].map(i => slot(i) ? { t: `🗑${i + 1}`, cb: `ptd:${slot(i).id}:${m.page}` } : NOP);
const nav = [m.page > 0 ? { t: '◀️', cb: `pmn:${m.page - 1}` } : NOP,
             m.page + 1 < pages ? { t: '▶️', cb: `pmn:${m.page + 1}` } : NOP];
return targets.map(chat_id => ({ json: { chat_id, message_id: m.message_id, total: m.total, text, pick, drop, nav } }));

